const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});

const clientId = String(payload.clientId || payload.client_id || 'CLIENT-CORP').trim();
const clientName = String(payload.clientName || payload.name || 'Enterprise Client').trim();
const clientEmail = String(payload.clientEmail || payload.email || '').trim().toLowerCase();
const quarter = String(payload.quarter || 'Q4 2026').trim();
const tier = String(payload.tier || 'Enterprise SLA').trim();
const annualContractValue = Number(payload.annualContractValue || payload.acv || 250000);
const projectsActive = Number(payload.projectsActive || 3);

const uptimePercentage = Number(payload.uptimePercentage || 99.98);
const totalApiRequests = Number(payload.totalApiRequests || 1420000);
const slaComplianceRate = Number(payload.slaComplianceRate || 100);
const hoursSavedAutomation = Number(payload.hoursSavedAutomation || 360);
const estimatedCostSavingsINR = Number(payload.estimatedCostSavingsINR || 1800000);
const csatAverage = Number(payload.csatAverage || 9.8);
const milestonesDelivered = Number(payload.milestonesDelivered || 8);

const strategicRoadmapRecommendations = [
  'Scale production workloads to multi-region active-active cluster',
  'Deploy zero-trust automated agent pipelines for continuous validation',
  'Integrate automated telemetry alerting with instant failover recovery'
];

const isEnterprise = tier.toLowerCase().includes('enterprise') || annualContractValue >= 200000;

const analytics = {
  clientId,
  clientName,
  clientEmail,
  quarter,
  tier,
  annualContractValue,
  projectsActive,
  performance: {
    uptimePercentage,
    totalApiRequests,
    slaComplianceRate,
    hoursSavedAutomation,
    estimatedCostSavingsINR,
    csatAverage,
    milestonesDelivered
  },
  strategicRoadmapRecommendations,
  isEnterprise,
  computedAt: new Date().toISOString()
};

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    analytics,
    isEnterprise
  }
}];

